const E=LegalEngine,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rules;try{rules=JSON.parse(localStorage.getItem('ip-rules-v1'))||structuredClone(E.defaults);if(!Array.isArray(rules)||!rules.every(r=>r && typeof r.id==='string' && typeof r.title==='string' && Array.isArray(r.keywords) && E.sources.some(s=>s.id===r.source)))throw Error();}catch{rules=structuredClone(E.defaults)}
let state={page:'intel',role:'甲方',scenario:'FDE 驻场开发',text:'',results:null,filter:'全部',query:'',saved:[],type:'全部'};
function persist(){try{localStorage.setItem('ip-rules-v1',JSON.stringify(rules))}catch{toast('浏览器存储不可用，本次修改仅在当前页面保留')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
function source(id){const s=E.sources.find(s=>s.id===id);modal(`<div class="eyebrow">OFFICIAL SOURCE / 法律依据</div><h2 style="margin:15px 0">${s.title}</h2><p>${s.agency} · 发布 ${s.date}</p><span class="badge">${s.article}</span><p>${s.summary}</p><div class="quote">来源核验：2026-10-20 · 官方页面<br>该来源摘要为解释性整理，并非完整法律意见。具体适用须核查正文、效力及事实。</div><p><a href="${s.url}" target="_blank" rel="noopener noreferrer">访问官方原文 ↗</a></p>`)}
function render(){const config={intel:['法律情报中心','让每一次法律变化，成为可执行的业务洞察。','↻ 刷新情报'],review:['合同审查工作台','从合作场景出发，让知识产权边界更清晰。','↓ 导出审查报告'],rules:['知识库规则管理','将法律依据沉淀为团队可复用的审查标准。','＋ 新建规则']};const c=config[state.page];$('#title').textContent=c[0];$('#crumb').textContent=c[0];$('#subtitle').textContent=c[1];$('#topAction').textContent=c[2];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#view').innerHTML=state.page==='intel'?intel():state.page==='review'?backendPanel()+review()+chatPanel():knowledge();bind();bindBackend()}
let intelData={items:[],status:[],updatedAt:null},intelError='';
async function loadIntel(){try{const res=await fetch('/api/intel');if(!res.ok)throw Error();const v=await res.json();if(!Array.isArray(v.items)||!Array.isArray(v.status))throw Error();intelData=v;intelError=''}catch{intelError='情报服务暂不可用，请检查连接。'}if(state.page==='intel')render()}
function intel(){const list=intelData.items.filter(s=>(state.filter==='全部'||s.type===state.filter)&&(s.title+s.summary).includes(state.query));return `<div class="notice">${esc(intelError||('最近整理：'+(intelData.updatedAt?new Date(intelData.updatedAt).toLocaleString('zh-CN'):'尚未运行每日任务')))} · 发现日期不等于发布日期；AI 摘要待人工核验。</div><div class="filters">${['全部','法律法规','司法案例','政策动态'].map(f=>`<button class="chip ${state.filter===f?'on':''}" data-filter="${f}">${f}</button>`).join('')}<input id="search" placeholder="搜索情报…" value="${esc(state.query)}"></div><div class="grid"><div class="panel">${list.map(s=>`<article class="item"><div class="meta"><span class="badge">${esc(s.type)}</span> ${esc(s.agency)} · ${esc(s.reviewStatus)}</div><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><p>业务提示：${esc(s.impact)}</p><div class="count">发布：${esc(s.publishedAt||'原文未识别，请核查')} · 首次发现：${esc(s.discoveredAt)}</div><p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">查看官方原文 ↗</a></p></article>`).join('')||'<div class="empty">暂无已整理情报。每日任务完成后会自动更新，不展示预置样本。</div>'}</div><div class="panel rail"><h2>采集状态</h2>${intelData.status.map(s=>`<div class="source-row">${esc(s.name)}<small>${s.ok?'列表读取成功':'采集失败'} · 本轮整理 ${esc(s.processed)} 篇${s.error?' · '+esc(s.error):''}</small></div>`).join('')||'<p>等待首次采集</p>'}<p>仅覆盖已配置官方来源，不代表全网或全部新增法律。首次运行可能收录历史内容；历史情报不自动成为合同审查依据。</p></div></div>`}
function review(){return `<div class="toolbar"><label>审查立场</label><div class="seg">${['甲方','乙方','中立'].map(r=>`<button class="${state.role===r?'on':''}" data-role="${r}">${r}</button>`).join('')}</div><label for="scenario">合作场景</label><select id="scenario">${['FDE 驻场开发','AI 大模型','委托研发','技术许可'].map(s=>`<option ${state.scenario===s?'selected':''}>${s}</option>`).join('')}</select><span class="count">规则集 v0.1 · ${rules.filter(r=>r.enabled).length} 条启用</span></div><div class="review-grid"><div class="panel"><div class="panel-head"><h2>合同原文</h2></div><div class="pad"><p style="margin-top:0;font-size:12px">粘贴合同知识产权条款，或导入 UTF-8 TXT 文件。</p><textarea id="contract" aria-label="合同原文" placeholder="请粘贴需要审查的合同条款…">${esc(state.text)}</textarea><div class="editor-foot"><label class="link">导入 TXT<input type="file" id="file" accept=".txt,text/plain" style="display:none"></label><button class="primary" id="run">开始规则审查 →</button></div><div class="rail-note">规则模式仅检测关键词；AI 模式进行语义分析。<br>AI 模式将合同发送至模型服务，所有结果均须法务复核。</div></div></div><div class="panel"><div class="panel-head"><h2>审查发现 <span class="count">${state.results?'/ '+state.results.length+' 项':''}</span></h2><span class="badge amber">需法务复核</span></div>${state.results?state.results.length?state.results.map(r=>`<div class="result"><div class="meta"><span class="badge ${r.level==='高'?'red':'amber'}">${r.level}优先级</span><span>${esc(r.id)} · ${state.role}立场</span></div><h3>${esc(r.title)}</h3><p>${esc(r.evidence)}</p><div class="quote">合同线索：${esc(r.originalText!==undefined?(r.originalText||'未发现对应原文，属于条款缺失建议'):state.text.slice(0,140))}${r.originalText===undefined&&state.text.length>140?'…':''}</div><p>${esc(r.note)}</p><details><summary class="link">查看建议条款</summary><div class="quote">${esc(r.draft)}</div><button class="link" data-copy="${esc(r.id)}">复制建议条款</button></details><div class="item-bottom">${(r.sourceIds||(r.source?[r.source]:[])).map(id=>`<button class="link" data-source="${esc(id)}">依据：${esc(E.sources.find(s=>s.id===id)?.title||id)} ↗</button>`).join('')||'<span class="count">依据不足，需补充核验</span>'}<span class="count">${r.status}</span></div></div>`).join(''):'<div class="empty">本次没有返回审查发现。请核对规则与审查范围。<br>没有结果不代表无风险。</div>':'<div class="empty"><span style="font-size:35px">▤</span><br>准备好，开始一次有依据的审查<br><small>选择合作场景与立场后，点击开始规则审查</small></div>'}</div></div>`}
function knowledge(){return `<div class="stats">${[['规则总数',rules.length,'业务规则 · 浏览器本地存储'],['已启用',rules.filter(r=>r.enabled).length,'用于合同审查'],['覆盖来源',2,'官方法律依据'],['规则版本','v0.1','编辑后即时生效']].map(a=>`<div class="stat"><label>${a[0]}</label><strong>${a[1]}</strong><small>${a[2]}</small></div>`).join('')}</div><div class="panel"><div class="panel-head"><h2>审查规则库</h2><button class="link" id="reset">恢复默认规则</button></div><div class="rule-row rule-header"><span>规则名称 / 编号</span><span>适用场景</span><span>优先级</span><span>操作</span><span>启用</span></div>${rules.map(r=>`<div class="rule-row"><div>${esc(r.title)}<small>${r.id} · 关键词：${esc(r.keywords.join('、'))}</small></div><span class="count">${r.scenario}</span><span class="badge ${r.level==='高'?'red':'amber'}">${r.level}</span><button class="link" data-edit="${r.id}">编辑规则 ↗</button><input class="switch" type="checkbox" data-toggle="${r.id}" ${r.enabled?'checked':''} aria-label="启用 ${esc(r.title)}"></div>`).join('')}</div><div class="rail-note">规则的业务优先级由团队设定，并非对法律责任的自动判定。修改规则后，工作台旧结果会清空，需要重新审查。</div>`}
function invalidate(){state.results=null;resetBackendContext()}
function edit(id){const r=rules.find(r=>r.id===id)||{id:'IP-'+Date.now(),title:'',scenario:'全部',level:'中',source:'civil',keywords:[],note:'',enabled:true};modal(`<h2>${id?'编辑':'新建'}审查规则</h2><form id="ruleform" class="pad"><p>规则名称</p><input name="title" required maxlength="80" value="${esc(r.title)}" style="width:100%"><p>适用场景 / 优先级 / 法律来源</p><select name="scenario">${['全部','FDE 驻场开发','AI 大模型','委托研发','技术许可'].map(s=>`<option ${r.scenario===s?'selected':''}>${s}</option>`).join('')}</select> <select name="level">${['高','中','低'].map(s=>`<option ${r.level===s?'selected':''}>${s}</option>`).join('')}</select><p><select name="source">${E.sources.map(s=>`<option value="${s.id}" ${r.source===s.id?'selected':''}>${s.title}</option>`).join('')}</select></p><p>检测关键词（以中文逗号分隔）</p><input name="keywords" required value="${esc(r.keywords.join('，'))}" style="width:100%"><p>审查要点</p><textarea name="note" required>${esc(r.note)}</textarea><button class="primary">保存规则</button></form>`);$('#ruleform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={...r,...Object.fromEntries(f),keywords:f.get('keywords').split(/[,，]/).map(s=>s.trim()).filter(Boolean)};if(!v.title.trim()||!v.keywords.length)return toast('请填写名称和有效关键词');if(id)rules=rules.map(x=>x.id===id?v:x);else rules.push(v);persist();invalidate();$('#modal').close();render();toast('规则已保存')};}
function download(){if(!state.results)return toast('请先运行审查');const report={engine:backendState.resultMode==='ai'?'AI 语义审查，非法律意见':'关键词规则引擎，非法律意见',model:backendState.resultMode==='ai'?backendState.model:null,questions:backendState.questions,chat:backendState.messages,role:state.role,scenario:state.scenario,contract:state.text,reviewedAt:new Date().toISOString(),results:state.results.map(r=>({...r,sourceDetail:E.sources.filter(s=>(r.sourceIds||(r.source?[r.source]:[])).includes(s.id))}))};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));a.href=url;a.download='知界-审查报告.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function bind(){document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>source(b.dataset.source));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.page=b.dataset.go;render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)};document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{state.role=b.dataset.role;invalidate();render()});if($('#scenario'))$('#scenario').onchange=e=>{state.scenario=e.target.value;invalidate();render()};if($('#contract'))$('#contract').oninput=e=>{state.text=e.target.value;if(state.results||backendState.sessionId){invalidate();const pos=e.target.selectionStart;render();$('#contract').focus();$('#contract').setSelectionRange(pos,pos)}};if($('#run'))$('#run').onclick=()=>{if(!state.text.trim())return toast('请先输入合同文本');state.results=E.review(state.text,state.scenario,state.role,rules);render();toast('规则审查完成，请逐项复核')};if($('#sample'))$('#sample').onclick=()=>{state.text=state.scenario==='AI 大模型'?'甲方提供业务数据，乙方进行模型微调。所有模型与输出内容归乙方所有。乙方可继续使用甲方数据进行训练。':'甲方委托乙方进行驻场系统开发。交付系统上线即视为验收。知识产权由双方另行协商。';invalidate();render()};if($('#file'))$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)return toast('请导入小于 1MB 的 TXT');state.text=await f.text();invalidate();render();toast('已在本地导入文本')};document.querySelectorAll('[data-toggle]').forEach(b=>b.onchange=()=>{rules.find(r=>r.id===b.dataset.toggle).enabled=b.checked;persist();invalidate();render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(state.results.find(r=>r.id===b.dataset.copy).draft);toast('已复制建议条款')}catch{toast('复制不可用，请展开后手动选择文本')}});if($('#reset'))$('#reset').onclick=()=>{modal('<h2>恢复默认规则？</h2><p>这会替换当前浏览器中的规则修改。</p><button class="secondary" id="confirmReset">确认恢复</button>');$('#confirmReset').onclick=()=>{rules=structuredClone(E.defaults);persist();invalidate();$('#modal').close();render()}};$('#topAction').onclick=state.page==='intel'?()=>loadIntel():state.page==='review'?download:()=>edit();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()});render();

loadIntel();
